  /// The field's own wording of the field-error codes its checks report (message keys by code); a
  /// code it does not word shows the framework's text (`violationText`).
  final Map<String, String> wording;

  final bool required;
  final int? minLength;
  final int? maxLength;
  final num? min;
  final num? max;
  final bool positive;
  final RegExp? pattern;
  final int? precision;
  final int? scale;

  /// The first check [value] fails, or `null` when it meets them all. An
  /// unset value fails only `required`.
  FieldViolation? violation(Object? value) {
    final empty = value == null || (value is String && value.isEmpty);
    if (empty) {
      return required ? FieldViolation.required : null;
    }
    final shortest = minLength;
    final longest = maxLength;
    // A length counts code points, as on every target (`String.length`
    // counts UTF-16 code units, so an emoji would count twice).
    if (value is String && shortest != null && value.runes.length < shortest) {
      return FieldViolation.tooShort;
    }
    if (value is String && longest != null && value.runes.length > longest) {
      return FieldViolation.tooLong;
    }
    if (!_inRange(value)) {
      return FieldViolation.outOfRange;
    }
    final declared = pattern;
    if (declared != null && value is String && !declared.hasMatch(value)) {
      return FieldViolation.mismatch;
    }
    final digits = precision;
    if (digits != null && !_fitsDigits('$value', digits, scale)) {
      return FieldViolation.mismatch;
    }
    return null;
  }

  bool _inRange(Object value) {
    final lowest = min;
    final highest = max;
    if (lowest == null && highest == null && !positive) {
      return true;
    }
    // An exact decimal is held as its decimal text; it is compared by the number it reads as.
    final number = value is num ? value : num.tryParse('$value');
    if (number == null) {
      return false;
    }
    return (lowest == null || number >= lowest) && (highest == null || number <= highest) && (!positive || number > 0);
  }

  static bool _fitsDigits(String text, int precision, int? scale) {
    final places = scale ?? 0;
    final integers = places > 0 ? (precision - places < 1 ? 1 : precision - places) : precision;
    final pattern = places > 0 ? RegExp('^-?\\d{1,$integers}(\\.\\d{1,$places})?\$') : RegExp('^-?\\d{1,$integers}\$');
    return pattern.hasMatch(text);
  }
}

/// A route form's shape: every field path it holds (a group's and a repeatable
/// field's own path among them, an element as `[]`) with the checks of each
/// leaf field.
