      walk(form.valueAt(path), path, path);
    }
    return failed;
  }

  /// The paths one level under [pattern] (`''`: the top-level members).
  Iterable<String> _childrenOf(String pattern) => fields.keys.where((path) {
    if (pattern.isEmpty) {
      return !path.contains('.') && !path.contains('[');
    }
    final rest = path.startsWith('$pattern.') ? path.substring(pattern.length + 1) : null;
    return rest != null && !rest.contains('.') && !rest.contains('[');
  });

  /// [form]'s value with only the members this shape holds, at every depth --
  /// what its body model decodes.
  Map<String, Object?> members(FormValue form) {
    Object? keep(Object? value, String pattern) {
      if (value is Map<String, Object?>) {
        return {
          for (final entry in value.entries)
            if (fields.containsKey(pattern.isEmpty ? entry.key : '$pattern.${entry.key}')) entry.key: keep(entry.value, pattern.isEmpty ? entry.key : '$pattern.${entry.key}'),
        };
